  }
  nums[nums.length - 1] = first;
}

public static int mySqrt(int x) {
  if (x < 2) {
    return x;
  }
  int left = 1;
  int right = x / 2;
  int ans = 0;
  while (left <= right) {
    int mid = left + (right - left) / 2;
    if ((long) mid * mid <= x) {
      ans = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return ans;
}

